/* Temporary wrappers for owned diagnostic builds; never retain packet bytes. */
#include <sys/socket.h>
#include <poll.h>
#include <errno.h>
extern void halo2_ice_packet_trace(const char *,int,long,int,const struct sockaddr *,socklen_t);
extern void halo2_ice_poll_trace(const struct pollfd *,nfds_t,int);
ssize_t halo2_ice_sendto(int fd,const void* data,size_t length,int flags,const struct sockaddr* address,socklen_t size){
    const ssize_t result=sendto(fd,data,length,flags,address,size);const int saved=errno;
    halo2_ice_packet_trace("send",fd,result,result<0?saved:0,address,size);errno=saved;return result;
}
ssize_t halo2_ice_recvfrom(int fd,void* data,size_t length,int flags,struct sockaddr* address,socklen_t* size){
    const ssize_t result=recvfrom(fd,data,length,flags,address,size);const int saved=errno;
    halo2_ice_packet_trace("receive",fd,result,result<0?saved:0,result>=0?address:0,result>=0?*size:0);errno=saved;return result;
}
int halo2_ice_poll(struct pollfd* descriptors,nfds_t count,int timeout){
    const int result=poll(descriptors,count,timeout);const int saved=errno;
    halo2_ice_poll_trace(descriptors,count,result);errno=saved;return result;
}

