#include <nlohmann/json.hpp>
#include <arpa/inet.h>
#include <ifaddrs.h>
#include <poll.h>
#include <sys/socket.h>
#include <unistd.h>
#include <array>
#include <chrono>
#include <cstring>
#include <mutex>
#include <thread>
#include <vector>
#include <string_view>

namespace {
using Json=nlohmann::json;
std::mutex mutex;
Json trace={{"packets",Json::array()},{"poll_calls",0},{"poll_socket_readable",0},{"poll_other_readable",0}};
struct Endpoint {int fd;sockaddr_storage address;socklen_t size;};
std::vector<Endpoint> endpoints;
unsigned port(const sockaddr* address){
    if(!address)return 0;
    if(address->sa_family==AF_INET)return ntohs(reinterpret_cast<const sockaddr_in*>(address)->sin_port);
    if(address->sa_family==AF_INET6)return ntohs(reinterpret_cast<const sockaddr_in6*>(address)->sin6_port);
    return 0;
}
std::string interface(const sockaddr* address){
    if(!address)return {};
    in_addr mapped{};
    if(address->sa_family==AF_INET6&&IN6_IS_ADDR_V4MAPPED(&reinterpret_cast<const sockaddr_in6*>(address)->sin6_addr))
        std::memcpy(&mapped,reinterpret_cast<const unsigned char*>(&reinterpret_cast<const sockaddr_in6*>(address)->sin6_addr)+12,4);
    ifaddrs* list{};getifaddrs(&list);std::string result;
    for(auto* item=list;item;item=item->ifa_next){
        if(!item->ifa_addr)continue;
        if(item->ifa_addr->sa_family==AF_INET){
            const auto own=reinterpret_cast<const sockaddr_in*>(item->ifa_addr)->sin_addr.s_addr;
            if((address->sa_family==AF_INET&&own==reinterpret_cast<const sockaddr_in*>(address)->sin_addr.s_addr)||
               (mapped.s_addr&&own==mapped.s_addr))result=item->ifa_name;
        }else if(item->ifa_addr->sa_family==AF_INET6&&address->sa_family==AF_INET6&&
            std::memcmp(&reinterpret_cast<const sockaddr_in6*>(item->ifa_addr)->sin6_addr,
                        &reinterpret_cast<const sockaddr_in6*>(address)->sin6_addr,16)==0)result=item->ifa_name;
    }
    freeifaddrs(list);return result;
}
}
extern "C" void halo2_ice_packet_trace(const char* operation,int fd,long count,int error,const sockaddr* address,socklen_t size){
    if(count<0)return; // Normal nonblocking EAGAIN is not a received datagram.
    sockaddr_storage local{};socklen_t length=sizeof(local);getsockname(fd,reinterpret_cast<sockaddr*>(&local),&length);
    Json row={{"operation",operation},{"fd",fd},{"bytes",count},{"errno",error},{"socket_family",local.ss_family},
        {"local_port",port(reinterpret_cast<sockaddr*>(&local))},{"other_port",port(address)},
        {"other_family",address?int(address->sa_family):0},{"other_size",size},{"other_local_interface",interface(address)}};
    if(local.ss_family==AF_INET6){
        row["bound_any"]=bool(IN6_IS_ADDR_UNSPECIFIED(&reinterpret_cast<const sockaddr_in6*>(&local)->sin6_addr));
        int value{};socklen_t option_size=sizeof(value);
        if(getsockopt(fd,IPPROTO_IPV6,IPV6_V6ONLY,&value,&option_size)==0)row["ipv6_only"]=value;
    }
    sockaddr_storage peer{};socklen_t peer_size=sizeof(peer);
    row["udp_connected"]=getpeername(fd,reinterpret_cast<sockaddr*>(&peer),&peer_size)==0;
    if(address&&address->sa_family==AF_INET6)row["other_ipv4_mapped"]=bool(IN6_IS_ADDR_V4MAPPED(&reinterpret_cast<const sockaddr_in6*>(address)->sin6_addr));
#ifdef __APPLE__
    if(address)row["other_native_length"]=address->sa_len;
#endif
    std::lock_guard lock(mutex);
    if(std::string_view(operation)=="send"&&address&&size<=sizeof(sockaddr_storage)){
        const bool found=std::any_of(endpoints.begin(),endpoints.end(),[&](const auto& item){return item.fd==fd&&item.size==size&&std::memcmp(&item.address,address,size)==0;});
        if(!found){Endpoint value{fd,{},size};std::memcpy(&value.address,address,size);endpoints.push_back(value);}
    }
    if(trace["packets"].size()<256)trace["packets"].push_back(std::move(row));
}
extern "C" void halo2_ice_poll_trace(const pollfd* descriptors,nfds_t count,int result){
    std::lock_guard lock(mutex);trace["poll_calls"]=trace["poll_calls"].get<unsigned>()+1;
    for(nfds_t i=0;result>0&&i<count;++i)if(descriptors[i].revents&POLLIN){
        int type{};socklen_t size=sizeof(type);const bool socket=getsockopt(descriptors[i].fd,SOL_SOCKET,SO_TYPE,&type,&size)==0;
        const char* key=socket?"poll_socket_readable":"poll_other_readable";
        trace[key]=trace[key].get<unsigned>()+1;
    }
}
nlohmann::json halo2_ice_socket_trace(){std::lock_guard lock(mutex);return trace;}
nlohmann::json halo2_ice_socket_controls(){
    std::vector<Endpoint> targets;{std::lock_guard lock(mutex);targets=endpoints;}
    Json results=Json::array();
    for(const auto& target:targets){
        Json row={{"fd",target.fd},{"other_port",port(reinterpret_cast<const sockaddr*>(&target.address))},
            {"interface",interface(reinterpret_cast<const sockaddr*>(&target.address))}};
        char peek{};const auto queued=recv(target.fd,&peek,1,MSG_PEEK|MSG_DONTWAIT);
        row["queued_before_control"]=queued;row["peek_errno"]=queued<0?errno:0;
        std::array<char,100> payload{};payload.fill('X');
        const auto count=sendto(target.fd,payload.data(),payload.size(),0,reinterpret_cast<const sockaddr*>(&target.address),target.size);
        row["plain_control_send_bytes"]=count;row["plain_control_errno"]=count<0?errno:0;
        results.push_back(std::move(row));
    }
    std::this_thread::sleep_for(std::chrono::milliseconds(200));
    return results;
}

